INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 7, 0.0, 10.85, "訓練成功、おめでとうございます\n褒めるべき時にはしっかり褒めるのも\n教官の務めですものね。それとも、\n罵られる方が好みですか？　クスクス", 1, 100, 100, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 2, 0.0, 11.15, "厳しい訓練も、終わってみれば\n短く感じるものですわね。\n正直、私は暴れ足りないくらい…\nいえ、何でもありませんわ。クスクス", 1, 101, 101, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 5, 0.0, 6.4, "行く手を阻む忌々しい邪魔者を\n蹴散らして、見事ゴールイン…！\nまるで私とあのおかたの人生を\n象徴するような道のりでした…", 7, 102, 102, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 3, 0.0, 0.0, "まったくもって不甲斐ない結果です\nしかし、挽回の機会はまだありますわ\n次はゴミ虫の地位から脱却できるよう\n死力を尽くしなさい。いいですね？", 3, 103, 103, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 8, 0.0, 2.43, "クスクス…ああご心配なさらず\nなんとも情けない成績を残す輩には\nどんな罰が相応しいか、考えている\nだけですので…クスクスクス", 2, 104, 104, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 3, 0.0, 9.08, "私が教官として認められなければ、\nあのおかたを失望させてしまう…\nそれだけはあってはなりません\nあなた方も、わかっていますわね？", 4, 105, 105, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 6, 0.0, 0.0, "まずまずの結果ではありますが、\nこの程度で満足してもらっては\n困りますわ。エリコ班の一員として、\nより高みを目指していただきますので", 6, 106, 106, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 8, 0.0, 10.6, "私の指導を受けながら、この結果は…\nもっと真剣に考えねばなりませんね\nあなた方が怠けずにいるには、\nどんなしつけが必要かを…クスクス", 3, 107, 107, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 4, 0.0, 7.54, "ひとまず訓練をこなしたご褒美か、\n実力を出しきれたとは言えない罰か…\nみなさんにどちらを与えるべきか\n少し悩む結果ですわね", 6, 108, 108, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 7, 0.0, 11.5, "なかなかいい戦いぶりでしたわ\nこれもあなた方の頑張りと、何より\n優秀な教官である私の教育の賜物\nそうですわね？　クスクスクス…", 2, 109, 109, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 1, 0.0, 8.83, "これだけ進めたのならば合格点ですわ\nでも、もっと高みを目指したいと\n思っているのなら…さらなる訓練にも\n付き合って差し上げましょう", 2, 110, 110, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 2, 0.0, 6.68, "未熟で頼りなかったあなた方が、\n見違えるように成長しました\nなるほど…これこそが、教官冥利に\n尽きるという気持ちなのですね", 1, 111, 111, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 2, 0.0, 8.8, "まさかあなた方が、私の予想すら\n超える力を発揮するとは…驚きました\nもはやゴミ虫などではありません\n一人前の騎士として胸を張りなさい", 6, 112, 112, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 1, 0.0, 8.9, "クスクス、見事な働きです\nみなさんならできると信じていました\n他でもない私の指導を受けた、\nエリコ班の優秀な新兵なのですから", 2, 113, 113, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129901, "2024/03/31 12:00:00", 24, 5, 0.0, 3.7, "なんてすばらしい成績…！\n今日という日は『あのおかたを想い\nエリコが限界を超えた記念日』として\n歴史に刻まれることでしょう…！", 2, 114, 114, "エリコ");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 2, 0.0, 7.6, "よし、いい訓練になったな\nおまえたちもよく動けてたし、\nちゃんと成長できてると思うぜ\nその調子で頑張れよっ", 1, 200, 200, "マコト");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 1, 0.0, 2.25, "ひとまずゴールおめでとう！\nでも、努力は継続してこそだからな\nおまえたちにやる気があるなら、\n何度だって付き合ってやるよ", 2, 201, 201, "マコト");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 1, 0.0, 3.28, "行軍訓練はこれにて完了！\n…なーんて思ってないよな？\n学んだことが体に染みつくまで\n地道に繰り返すのが練習ってもんさ", 2, 202, 202, "マコト");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 1, 0.0, 2.98, "みんなに無理をさせちまったか…\nでもこれで諦めることはないぜ\n次はきっとうまくいく。そう信じて\n鍛え続ければ、道は開けるはずだ！", 4, 203, 203, "マコト");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 1, 0.0, 3.0, "こいつは悔しい結果だな…\nま、反省点はいろいろあったし\nひとつずつ乗り越えていこう\nあたしたちで力を合わせて、なっ！", 4, 204, 204, "マコト");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 2, 0.0, 10.3, "おまえたちはまだ未熟な訓練兵、\n失敗を必要以上に悔やむことはねえよ\nでも実戦じゃこうはいかないからな\n次は気合を入れ直していけよっ！", 1, 205, 205, "マコト");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 1, 0.0, 2.93, "これがおまえたちの全力？\nいやいや、そんなはずはないよなっ\nおまえらならもっと強くなれる！\nあたしが言うんだ、間違いないぜ！", 6, 206, 206, "マコト");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 1, 0.0, 9.3, "おまえたちの実力を考えりゃ、\nベストを尽くせたとは言えない成績だ\nなら、次やるべきことも決まってる\n気持ちを切り替えて、鍛え直すんだ！", 3, 207, 207, "マコト");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 1, 0.0, 6.9, "まだまだ課題がある内容だったな～\n無駄な動き、判断の遅れ…\nそういうのをしっかり直していけば、\n記録ももっと伸びるはずだっ", 4, 208, 208, "マコト");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 2, 0.0, 0.0, "ここまでいけりゃ、合格点！\nむしろ、最初の頼りなさを思えば\nすげえ成長してるんじゃねえか？\n胸を張れる結果だと思うぜっ！", 2, 209, 209, "マコト");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 2, 0.0, 5.95, "なかなかハードな訓練だったけど、\nみんなしっかりついてこられたな\n地道に続けた基礎トレの成果が\n形になってる、その証だぜっ", 1, 210, 210, "マコト");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 1, 0.0, 6.73, "今回の訓練もよく頑張ったな！\nしっかり休んで次に備えろよ！\nなんつーか、教え子が成長してくのを\n見るのは楽しいもんだな…", 2, 211, 211, "マコト");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 2, 0.0, 0.0, "おまえら、すげえじゃねえか！\nこれならもう、ひよっこ新兵なんて\n言えねえな。きっと騎士団でも\n大活躍間違いなしだぜ！", 2, 212, 212, "マコト");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 2, 0.0, 6.65, "敵との戦い方、状況判断の正確さ\n何より根性…どれも最高だったぞ！\nうかうかしてたら、教官のあたしまで\n追い抜かれちまうかもな…へへっ", 1, 213, 213, "マコト");
INSERT INTO `v1_39d4ad85cf612e2d1cd0efed33a6a3aa8b2ca3f1197b970959e647029d688c42` VALUES (0.0, "2030/12/17 14:59:59", 10142, 129801, "2024/03/31 12:00:00", 24, 1, 0.0, 3.05, "あたしの指導が良かった？\nいやいや、ここまで強くなれたのは、\n他でもないおまえたち自身が努力した\nおかげだよ。改めて…おめでとうっ！", 6, 214, 214, "マコト");
